    cin >> a >> b;
    // 总需求 = a/3 + b/4 = (4a + 3b) / 12，分子 4a+3b 一定是整数
    long long num = 4 * a + 3 * b;
    // 向上取整的整数写法：ceil(num / 12) = (num + 11) / 12
    long long ans = (num + 11) / 12;
    cout << ans << '\n';
    return 0;
}
```

