using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long total = 0;                 // 金额最大 1e15 级别，必须用 long long
    string name;
    long long v;
    for (int i = 0; i < n; ++i) {
        cin >> name >> v;
        if (name == "Q") {                // 只有小 Q 本人的记录才算数
            total += v;                   // v 为正=收到，v 为负=送出，统一相加即可
        }
    }

    cout << total << '\n';
    return 0;
}
```

### 易错点

比较完整名字，`QQ` 不算；累计金额使用 `long long`。

